const $ = (s, el=document) => el.querySelector(s);
const $$ = (s, el=document) => [...el.querySelectorAll(s)];
const LS_KEY = 'sh_absensi_v2';
const SESSION_KEY = 'sh_absensi_session_v2';
const DAYS = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
const SCHOOL_DAYS = ['Sabtu','Minggu','Senin','Selasa','Rabu','Kamis'];
const STUDENT_STATUSES = ['Aktif','Berhenti','Pindah','Lulus'];
const ATT_STATUSES = ['Hadir','Sakit','Izin','Alpa','Terlambat'];

function uid(prefix='id'){ return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`; }
function clone(v){ return JSON.parse(JSON.stringify(v)); }
function todayISO(){ const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function fmtDate(iso=todayISO()){ return new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(iso+'T12:00:00')); }
function esc(v=''){ return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function initials(name=''){ return String(name).split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase() || 'U'; }
function normalize(s=''){ return String(s).trim().toLowerCase().replace(/\s+/g,' '); }
function slug(s=''){ return normalize(s).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''); }
function statusClass(s=''){ return slug(s); }
function toast(msg){ const t=$('#toast'); if(!t)return; t.textContent=msg; t.classList.add('show'); clearTimeout(window.__toast); window.__toast=setTimeout(()=>t.classList.remove('show'),2400); }
function dayName(){ return DAYS[new Date().getDay()]; }
function titleCase(s=''){ return String(s).toLowerCase().replace(/(^|\s|\/)([a-z])/g,(m,a,b)=>a+b.toUpperCase()); }

function seedState(){
  const seed=clone(window.SH_SEED_DATA || {classes:[],subjects:[],teachers:[],students:[],schedules:[],teacherAliases:{},scheduleClassMap:{},meta:{}});
  const years=[{id:'yr_2026_2027_s1',name:'2026/2027',semester:'1',isActive:true}];
  return {
    version:2,
    seededAt:new Date().toISOString(),
    meta:seed.meta||{},
    settings:{schoolName:'SMA IT Sirajul Huda',photoRequired:false,activeAcademicYearId:years[0].id},
    users:[{id:'usr_superadmin',teacherId:null,name:'Super Admin',email:'superadmin@sirajulhuda.local',password:'admin123',role:'superadmin',status:'Aktif'}],
    teachers:seed.teachers||[], students:seed.students||[], classes:seed.classes||[], subjects:seed.subjects||[], academicYears:years,
    schedules:seed.schedules||[], teacherAliases:seed.teacherAliases||{}, scheduleClassMap:seed.scheduleClassMap||{},
    attendanceSessions:[], studentAttendance:[], teacherPresence:[], activityLogs:[]
  };
}
function loadState(){ try{ const s=JSON.parse(localStorage.getItem(LS_KEY)); return s&&s.version===2?s:seedState(); }catch{return seedState();} }
let state=loadState();
function saveState(){ localStorage.setItem(LS_KEY,JSON.stringify(state)); }
function logAction(text){ state.activityLogs.unshift({id:uid('log'),text,at:new Date().toISOString()}); state.activityLogs=state.activityLogs.slice(0,300); saveState(); }
function resetDemo(){ if(!confirm('Reset data lokal dan muat ulang data awal siswa, guru, dan jadwal?'))return; localStorage.removeItem(LS_KEY); localStorage.removeItem(SESSION_KEY); sessionStorage.removeItem(SESSION_KEY); location.reload(); }
function getActiveYear(){ return state.academicYears.find(x=>x.id===state.settings.activeAcademicYearId)||state.academicYears.find(x=>x.isActive)||state.academicYears[0]; }
function getTeacher(id){ return state.teachers.find(t=>t.id===id); }
function getClass(id){ return state.classes.find(c=>c.id===id); }
function getMyTeacher(){ return state.teachers.find(t=>t.id===currentUser?.teacherId); }
function roleLabel(user=currentUser){ if(!user)return ''; if(user.role==='superadmin')return 'Super Admin'; if(user.role==='admin')return 'Admin'; const t=state.teachers.find(x=>x.id===user.teacherId); return t?.type&&t.type!=='Belum ditentukan'?t.type:'Guru/Tendik'; }
function currentSession(){ const id=localStorage.getItem(SESSION_KEY)||sessionStorage.getItem(SESSION_KEY); return state.users.find(u=>u.id===id)||null; }
function unresolvedAliasCount(){ return Object.values(state.teacherAliases||{}).filter(v=>!v).length; }
function unresolvedClassCount(){ return Object.values(state.scheduleClassMap||{}).filter(v=>!v).length; }

function refreshScheduleLinks(){
  state.schedules.forEach(s=>{
    const tid=state.teacherAliases?.[s.teacherAlias]||null;
    s.teacherId=tid;
    s.teacherName=tid?(getTeacher(tid)?.name||s.teacherAlias):`${s.teacherAlias} (belum dipetakan)`;
    const cid=state.scheduleClassMap?.[s.scheduleClassName]||null;
    s.classId=cid;
    const t=getTeacher(tid); if(t&&t.type==='Belum ditentukan')t.type='Guru';
  });
}
refreshScheduleLinks(); saveState();

let currentUser=currentSession();
let currentPage='dashboard';
const authScreen=$('#authScreen'), appShell=$('#appShell');
const navConfig={
  superadmin:[['dashboard','⌂','Beranda'],['students','♟','Siswa'],['teachers','♙','Guru & Tendik'],['master','▦','Kelas & Mapel'],['years','◫','Tahun Ajaran'],['schedule','▤','Jadwal'],['reports','◔','Rekap'],['guide','?','Panduan'],['settings','⚙','Pengaturan']],
  admin:[['dashboard','⌂','Beranda'],['students','♟','Siswa'],['teachers','♙','Guru & Tendik'],['master','▦','Kelas & Mapel'],['years','◫','Tahun Ajaran'],['schedule','▤','Jadwal'],['reports','◔','Rekap'],['guide','?','Panduan']],
  guru:[['dashboard','⌂','Beranda'],['schedule','▤','Jadwal'],['attendance','✓','Absensi'],['reports','◔','Rekap'],['guide','?','Panduan']]
};

function initAuth(){
  $('#tabLogin').onclick=()=>switchAuth('login'); $('#tabRegister').onclick=()=>switchAuth('register');
  $('#teacherMissingBtn').onclick=()=>alert('Nama Anda belum terdaftar pada Data Guru/Tendik. Silakan hubungi Admin atau Super Admin.');
  $('#forgotPasswordBtn').onclick=()=>alert('Versi lokal belum mengirim email reset. Pada versi database online, reset password akan dikirim ke email akun.');
  $('#loginForm').onsubmit=e=>{e.preventDefault();login();}; $('#registerForm').onsubmit=e=>{e.preventDefault();registerTeacher();}; refreshRegisterTeachers();
}
function switchAuth(mode){ const login=mode==='login'; $('#tabLogin').classList.toggle('active',login); $('#tabRegister').classList.toggle('active',!login); $('#loginForm').classList.toggle('hidden',!login); $('#registerForm').classList.toggle('hidden',login); if(!login)refreshRegisterTeachers(); }
function refreshRegisterTeachers(){
  const sel=$('#registerTeacher'); if(!sel)return; const arr=state.teachers.filter(t=>t.status==='Aktif'&&!t.accountId).sort((a,b)=>a.name.localeCompare(b.name));
  sel.innerHTML='<option value="">Pilih nama Anda...</option>'+arr.map(t=>`<option value="${t.id}">${esc(t.name)}${t.type&&t.type!=='Belum ditentukan'?` — ${esc(t.type)}`:''}</option>`).join('');
}
function login(){
  const ident=normalize($('#loginIdentifier').value),pw=$('#loginPassword').value;
  const user=state.users.find(u=>u.status==='Aktif'&&(normalize(u.email)===ident||normalize(u.name)===ident)&&u.password===pw);
  if(!user)return toast('Nama/email atau password tidak sesuai.'); localStorage.setItem(SESSION_KEY,user.id); currentUser=user; currentPage='dashboard'; showApp();
}
function registerTeacher(){
  const teacherId=$('#registerTeacher').value,email=normalize($('#registerEmail').value),p1=$('#registerPassword').value,p2=$('#registerPassword2').value;
  if(!teacherId)return alert('Nama Anda belum terdaftar. Silakan hubungi Admin.'); if(p1!==p2)return toast('Ulangi password dengan benar.'); if(p1.length<6)return toast('Password minimal 6 karakter.'); if(state.users.some(u=>normalize(u.email)===email))return toast('Email sudah digunakan.');
  const t=getTeacher(teacherId); if(!t)return; if(t.accountId)return toast('Akun untuk nama ini sudah aktif.');
  const u={id:uid('usr'),teacherId:t.id,name:t.name,email,password:p1,role:'guru',status:'Aktif'}; state.users.push(u); t.accountId=u.id;t.email=email;saveState();logAction(`${t.name} mengaktifkan akun.`);
  alert(`Akun berhasil diaktifkan sebagai ${t.type==='Tendik'?'Tendik':'Guru/Tendik'}. Silakan masuk.`); switchAuth('login');$('#loginIdentifier').value=email;$('#loginPassword').value='';refreshRegisterTeachers();
}

function showApp(){
  if(!currentUser){authScreen.classList.remove('hidden');appShell.classList.add('hidden');return;}
  authScreen.classList.add('hidden');appShell.classList.remove('hidden');$('#sidebarName').textContent=currentUser.name;$('#sidebarRole').textContent=roleLabel();$('#sidebarAvatar').textContent=initials(currentUser.name);$('#profileButton').textContent=initials(currentUser.name);$('#logoutBtn').onclick=logout;$('#profileButton').onclick=openProfile;buildNav();renderPage();
}
function logout(){localStorage.removeItem(SESSION_KEY);sessionStorage.removeItem(SESSION_KEY);currentUser=null;showApp();switchAuth('login');}
function buildNav(){
  const items=navConfig[currentUser.role]||navConfig.guru; $('#sideNav').innerHTML=items.map(([id,ic,label])=>`<button class="nav-item ${currentPage===id?'active':''}" data-page="${id}"><span class="nav-icon">${ic}</span>${label}</button>`).join(''); $$('.nav-item').forEach(b=>b.onclick=()=>go(b.dataset.page));
  const mobile=currentUser.role==='guru'?items.slice(0,4):[['dashboard','⌂','Beranda'],['students','♟','Siswa'],['schedule','▤','Jadwal'],['reports','◔','Rekap']]; $('#bottomNav').innerHTML=mobile.map(([id,ic,label])=>`<button class="bottom-item ${currentPage===id?'active':''}" data-page="${id}"><span class="nav-icon">${ic}</span><span>${label}</span></button>`).join(''); $$('.bottom-item').forEach(b=>b.onclick=()=>go(b.dataset.page));
}
function go(page){currentPage=page;buildNav();renderPage();window.scrollTo({top:0,behavior:'smooth'});}
function setTitle(eyebrow,title){$('#pageEyebrow').textContent=eyebrow;$('#pageTitle').textContent=title;const y=getActiveYear();$('#activeYearBadge').textContent=y?`${y.name} • Semester ${y.semester}`:'Belum ada tahun aktif';}
function renderPage(){const allowed=(navConfig[currentUser.role]||[]).map(x=>x[0]);if(!allowed.includes(currentPage))currentPage='dashboard';const r={dashboard:renderDashboard,students:renderStudents,teachers:renderTeachers,master:renderMaster,years:renderYears,schedule:renderSchedule,attendance:renderAttendanceHub,reports:renderReports,guide:renderGuide,settings:renderSettings};(r[currentPage]||renderDashboard)();}
function stat(ic,val,label){return `<div class="card stat-card"><div class="stat-icon">${ic}</div><div><strong>${val}</strong><span>${label}</span></div></div>`;}
function byTime(a,b){return (a.start||'').localeCompare(b.start||'')||(a.scheduleClassName||'').localeCompare(b.scheduleClassName||'');}

function scheduleDoneIds(date=todayISO()){const ids=new Set();state.attendanceSessions.filter(x=>x.date===date).forEach(x=>(x.scheduleIds||[x.scheduleId]).filter(Boolean).forEach(id=>ids.add(id)));return ids;}
function scheduleBlocks(day,filter=()=>true){
  const arr=state.schedules.filter(s=>s.day===day&&filter(s)); const groups=new Map();
  arr.forEach(s=>{const k=[s.day,s.scheduleClassName,s.subjectName,s.teacherAlias,!!s.needsSubstitute].join('|');if(!groups.has(k))groups.set(k,[]);groups.get(k).push(s);});
  const blocks=[]; groups.forEach(list=>{list.sort(byTime);let cur=null;for(const s of list){if(cur&&cur.end===s.start){cur.end=s.end;cur.periods.push(s.period);cur.scheduleIds.push(s.id);}else{if(cur)blocks.push(cur);cur={id:s.id,day:s.day,start:s.start,end:s.end,periods:[s.period],scheduleIds:[s.id],scheduleClassName:s.scheduleClassName,classId:s.classId,subjectName:s.subjectName,teacherId:s.teacherId,teacherName:s.teacherName,teacherAlias:s.teacherAlias,needsSubstitute:!!s.needsSubstitute,reason:s.reason||''};}}if(cur)blocks.push(cur);});
  return blocks.sort(byTime);
}
function blockFromSchedule(scheduleId){const s=state.schedules.find(x=>x.id===scheduleId);if(!s)return null;return scheduleBlocks(s.day,b=>b.scheduleClassName===s.scheduleClassName&&b.subjectName===s.subjectName&&b.teacherAlias===s.teacherAlias&&!!b.needsSubstitute===!!s.needsSubstitute).find(b=>b.scheduleIds.includes(scheduleId))||null;}
function blockDone(block,date=todayISO()){const done=scheduleDoneIds(date);return block.scheduleIds.every(id=>done.has(id));}

function renderDashboard(){setTitle('BERANDA','Dashboard');const c=$('#pageContent');if(currentUser.role==='guru')return renderTeacherDashboard(c);const activeStudents=state.students.filter(s=>s.status==='Aktif').length;const activeTeachers=state.teachers.filter(t=>t.status==='Aktif').length;const today=todayISO(),day=dayName();const todaySessions=state.attendanceSessions.filter(x=>x.date===today);const todayBlocks=scheduleBlocks(day);const done=scheduleDoneIds(today);const pending=todayBlocks.filter(b=>!b.scheduleIds.every(id=>done.has(id)));const pres=state.teacherPresence.filter(x=>x.date===today).length;const setupProblems=unresolvedAliasCount()+unresolvedClassCount();
  c.innerHTML=`<div class="hero"><div><p>${fmtDate()}</p><h2>Selamat datang, ${esc(currentUser.name)}</h2><p>Data awal sudah memuat ${state.meta.activeStudentCount||activeStudents} siswa aktif dan jadwal 2026/2027.</p><button class="btn" onclick="go('schedule')">Lihat Jadwal Hari Ini</button></div><div class="hero-side"></div></div>
  ${setupProblems?`<div class="notice warning" style="margin-top:16px"><b>Setup jadwal belum selesai.</b> ${unresolvedAliasCount()} kode guru dan ${unresolvedClassCount()} kelas masih perlu dipetakan. <button class="link-btn" onclick="go('schedule')">Atur sekarang</button></div>`:''}
  <div class="grid cols-4" style="margin-top:16px">${stat('♟',activeStudents,'Siswa Aktif')}${stat('♙',activeTeachers,'Guru & Tendik')}${stat('◉',pres,'Pegawai Hadir')}${stat('✓',todaySessions.length,'Sesi Absensi')}</div>
  <div class="section-head"><div><h3>Kontrol Hari Ini</h3><p>${esc(day)} • ${todayBlocks.length} sesi jadwal setelah jam berurutan digabung.</p></div></div><div class="grid cols-2"><div class="card"><strong>Sudah diisi</strong><div style="font-size:32px;font-weight:900;margin-top:8px">${todayBlocks.length-pending.length}</div><span class="muted">blok jadwal selesai</span></div><div class="card"><strong>Belum diisi</strong><div style="font-size:32px;font-weight:900;margin-top:8px">${pending.length}</div><span class="muted">blok jadwal menunggu</span></div></div>
  <div class="section-head"><div><h3>Jadwal Belum Diisi</h3><p>Jam berurutan dengan kelas, mapel, dan guru yang sama otomatis menjadi satu sesi.</p></div></div>${pending.length?`<div class="grid">${pending.slice(0,10).map(scheduleCard).join('')}</div>`:`<div class="card empty">${todayBlocks.length?'Semua jadwal hari ini sudah diisi.':'Tidak ada jadwal sekolah hari ini.'}</div>`}`;
}
function scheduleCard(b){return `<div class="schedule-card"><div class="schedule-time"><strong>${esc(b.start)}–${esc(b.end)}</strong><span>Jam ${esc(b.periods.join(','))}</span></div><div class="schedule-info"><h4>${esc(b.scheduleClassName)}</h4><p>${esc(b.subjectName)} • ${esc(b.teacherName)}</p></div>${b.needsSubstitute?'<span class="status pending">Butuh Pengganti</span>':''}</div>`;}
function scheduleCardTeacher(b,done=false,replacement=false){return `<div class="schedule-card"><div class="schedule-time"><strong>${esc(b.start)}–${esc(b.end)}</strong><span>Jam ${esc(b.periods.join(','))}</span></div><div class="schedule-info"><h4>${esc(b.scheduleClassName)}</h4><p>${esc(b.subjectName)} • ${esc(b.teacherName)}</p>${!b.classId?'<small class="danger-text">Kelas belum dipetakan</small>':''}</div>${done?'<span class="status active">Selesai</span>':`<button class="btn ${replacement?'warning':'primary'} small" onclick="startAttendance('${b.id}',${replacement?'true':'false'})">${replacement?'Saya Menggantikan':'Isi Absensi'}</button>`}</div>`;}
function teacherPresenceToday(tid,date=todayISO()){return state.teacherPresence.find(x=>x.teacherId===tid&&x.date===date);}
function checkInTeacher(){const t=getMyTeacher();if(!t)return toast('Akun belum terhubung.');if(teacherPresenceToday(t.id))return toast('Kehadiran hari ini sudah tercatat.');state.teacherPresence.push({id:uid('prs'),teacherId:t.id,teacherName:t.name,date:todayISO(),time:new Date().toISOString(),method:'manual'});saveState();logAction(`${t.name} mencatat kehadiran.`);renderDashboard();toast('Kehadiran berhasil dicatat.');}
function ensureTeacherPresence(t){if(!teacherPresenceToday(t.id)){state.teacherPresence.push({id:uid('prs'),teacherId:t.id,teacherName:t.name,date:todayISO(),time:new Date().toISOString(),method:'mengajar'});}}
function renderTeacherDashboard(c){const t=getMyTeacher(),day=dayName(),today=todayISO();const own=scheduleBlocks(day,s=>s.teacherId===t?.id);const done=scheduleDoneIds(today);const pending=own.filter(b=>!b.scheduleIds.every(id=>done.has(id)));const replacements=scheduleBlocks(day,s=>s.needsSubstitute&&s.teacherId!==t?.id).filter(b=>!b.scheduleIds.every(id=>done.has(id)));const presence=t?teacherPresenceToday(t.id):null;
  c.innerHTML=`<div class="hero"><div><p>${fmtDate()}</p><h2>Selamat datang, ${esc(currentUser.name)} 👋</h2><p>${pending[0]?`Jadwal berikutnya: ${esc(pending[0].scheduleClassName)} • ${esc(pending[0].subjectName)} • ${esc(pending[0].start)}–${esc(pending[0].end)}`:'Tidak ada jadwal Anda yang menunggu absensi.'}</p>${pending[0]?`<button class="btn" onclick="startAttendance('${pending[0].id}')">Mulai Mengajar</button>`:''}</div><div class="hero-side"></div></div>
  <div class="presence-card ${presence?'done':''}"><div><b>${presence?'Kehadiran hari ini sudah tercatat':'Belum absen masuk'}</b><span>${presence?`Tercatat ${new Date(presence.time).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}`:'Tekan sekali saat datang ke sekolah.'}</span></div>${presence?'<span class="status active">Hadir</span>':'<button class="btn success small" onclick="checkInTeacher()">Saya Hadir</button>'}</div>
  <div class="grid cols-3" style="margin-top:16px">${stat('▤',own.length,'Sesi Hari Ini')}${stat('✓',own.length-pending.length,'Selesai')}${stat('↔',state.attendanceSessions.filter(x=>x.date===today&&x.teacherId===t?.id&&x.isSubstitute).length,'Menggantikan')}</div>
  <div class="section-head"><div><h3>Jadwal Saya Hari Ini</h3><p>Jam berurutan otomatis digabung menjadi satu absensi.</p></div></div>${own.length?`<div class="grid">${own.map(b=>scheduleCardTeacher(b,b.scheduleIds.every(id=>done.has(id)))).join('')}</div>`:'<div class="card empty">Belum ada jadwal Anda hari ini.</div>'}
  <div class="section-head"><div><h3>Kelas Membutuhkan Pengganti</h3><p>Guru maupun Tendik dapat mengambil kelas yang sudah ditandai Admin.</p></div></div>${replacements.length?`<div class="grid">${replacements.map(b=>scheduleCardTeacher(b,false,true)).join('')}</div>`:'<div class="card empty">Tidak ada kelas yang membutuhkan pengganti.</div>'}`;
}

function renderStudents(){setTitle('DATA MASTER','Data Siswa');const c=$('#pageContent');c.innerHTML=`<div class="section-head" style="margin-top:0"><div><h3>Buku Induk / Data Siswa</h3><p>Data awal berasal dari buku induk yang Anda kirim. Siswa berhenti tidak dihapus.</p></div><div class="toolbar"><input id="studentSearch" class="search" placeholder="Cari nama / NIS / kelas..."><button class="btn secondary" onclick="openStudentImport()">Import Excel</button><button class="btn primary" onclick="openStudentForm()">+ Tambah Siswa</button></div></div><div class="toolbar" style="margin-bottom:12px"><select id="studentStatusFilter" style="max-width:180px"><option value="">Semua Status</option>${STUDENT_STATUSES.map(x=>`<option>${x}</option>`).join('')}</select><select id="studentClassFilter" style="max-width:220px"><option value="">Semua Kelas</option>${state.classes.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><a class="btn ghost small" href="assets/Template_Import_Siswa_Absensi_Sirajul_Huda.xlsx" download>Download Template</a></div><div id="studentsTable"></div>`;$('#studentSearch').oninput=renderStudentsTable;$('#studentStatusFilter').onchange=renderStudentsTable;$('#studentClassFilter').onchange=renderStudentsTable;renderStudentsTable();}
function renderStudentsTable(){const root=$('#studentsTable');if(!root)return;const q=normalize($('#studentSearch')?.value),sf=$('#studentStatusFilter')?.value||'',cf=$('#studentClassFilter')?.value||'';const arr=state.students.filter(s=>(!sf||s.status===sf)&&(!cf||s.classId===cf)&&(!q||normalize(`${s.name} ${s.nis||''} ${s.nisn||''} ${s.className||''}`).includes(q))).sort((a,b)=>a.name.localeCompare(b.name));root.innerHTML=arr.length?`<div class="table-wrap"><table><thead><tr><th>NIS</th><th>Nama</th><th>L/P</th><th>Kelas</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${arr.map(s=>`<tr><td>${esc(s.nis||'-')}</td><td><strong>${esc(s.name)}</strong><br><span class="muted">${esc(s.nisn||'')}</span></td><td>${esc(s.gender||'-')}</td><td>${esc(s.className||'-')}</td><td><span class="status ${statusClass(s.status)}">${esc(s.status)}</span></td><td><button class="btn secondary small" onclick="openStudentForm('${s.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty">Tidak ada data siswa yang cocok.</div>';}
function openStudentForm(id=''){const s=state.students.find(x=>x.id===id)||{name:'',nis:'',nisn:'',gender:'L',classId:'',status:'Aktif'};openModal(id?'Edit Siswa':'Tambah Siswa','DATA SISWA',`<form id="studentForm" class="form-grid"><label>Nama Siswa<input id="sfName" value="${esc(s.name)}" required></label><label>NIS<input id="sfNis" value="${esc(s.nis||'')}"></label><label>NISN<input id="sfNisn" value="${esc(s.nisn||'')}"></label><label>Jenis Kelamin<select id="sfGender"><option value="L" ${s.gender==='L'?'selected':''}>Laki-laki</option><option value="P" ${s.gender==='P'?'selected':''}>Perempuan</option></select></label><label>Kelas<select id="sfClass"><option value="">Pilih kelas...</option>${state.classes.filter(x=>x.active).map(x=>`<option value="${x.id}" ${s.classId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Status<select id="sfStatus">${STUDENT_STATUSES.map(x=>`<option ${s.status===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="full"><button class="btn primary">Simpan</button></div></form>`);$('#studentForm').onsubmit=e=>{e.preventDefault();const cls=getClass($('#sfClass').value),y=getActiveYear();const payload={name:$('#sfName').value.trim(),nis:$('#sfNis').value.trim(),nisn:$('#sfNisn').value.trim(),gender:$('#sfGender').value,classId:cls?.id||'',className:cls?.name||'',status:$('#sfStatus').value,academicYear:y?.name||''};if(id){s.history=s.history||[];Object.assign(s,payload);logAction(`Data siswa ${s.name} diperbarui.`);}else{state.students.push({id:uid('stu'),...payload,history:[]});logAction(`Siswa ${payload.name} ditambahkan.`);}saveState();closeModal();renderStudents();toast('Data siswa tersimpan.');};}
function openStudentImport(){openModal('Import Data Siswa','IMPORT EXCEL',`<div class="notice info">Gunakan template. Sistem membaca Nama, NIS, NISN, L/P, Kelas, Tahun Ajaran, dan Status.</div><div class="stack" style="margin-top:14px"><label>Pilih file Excel / CSV<input id="studentImportFile" type="file" accept=".xlsx,.xls,.csv"></label><div id="importPreview"></div><button class="btn primary" id="runStudentImport" type="button">Baca & Import</button></div>`);$('#runStudentImport').onclick=importStudentsFile;}
async function importStudentsFile(){const file=$('#studentImportFile').files[0];if(!file)return toast('Pilih file terlebih dahulu.');if(typeof XLSX==='undefined')return alert('Pustaka Excel belum termuat. Hubungkan internet lalu coba lagi.');const data=await file.arrayBuffer(),wb=XLSX.read(data,{type:'array'}),sheet=wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(sheet,{defval:''});const get=(row,aliases)=>{const k=Object.keys(row).find(key=>aliases.includes(normalize(key)));return k?row[k]:'';};let add=0,upd=0,skip=0;for(const row of rows){const name=String(get(row,['nama siswa','nama santri','nama','nama lengkap'])).trim();if(!name){skip++;continue;}const nis=String(get(row,['nis','nomor induk'])).trim(),nisn=String(get(row,['nisn'])).trim(),gender=String(get(row,['l/p','lp','jenis kelamin','jk'])).trim().toUpperCase(),className=String(get(row,['kelas','nama kelas'])).trim();let status=titleCase(String(get(row,['status','status siswa','status santri'])).trim()||'Aktif');if(!STUDENT_STATUSES.includes(status))status='Aktif';let cls=state.classes.find(c=>normalize(c.name)===normalize(className));if(className&&!cls){cls={id:uid('cls'),name:className,unit:gender.startsWith('P')?'Putri':'Putra',active:true};state.classes.push(cls);}const ex=state.students.find(s=>(nis&&s.nis===nis)||(nisn&&s.nisn===nisn));const p={name,nis,nisn,gender:gender.startsWith('P')?'P':'L',classId:cls?.id||'',className:cls?.name||className,status,academicYear:getActiveYear()?.name||''};if(ex){Object.assign(ex,p);upd++;}else{state.students.push({id:uid('stu'),...p,history:[]});add++;}}saveState();logAction(`Import siswa: ${add} baru, ${upd} diperbarui.`);$('#importPreview').innerHTML=`<div class="notice success">${add} baru, ${upd} diperbarui, ${skip} dilewati.</div>`;toast('Import selesai.');}

function renderTeachers(){setTitle('DATA MASTER','Guru & Tendik');const c=$('#pageContent');c.innerHTML=`<div class="section-head" style="margin-top:0"><div><h3>Data Guru & Tendik</h3><p>${state.teachers.length} nama sudah dimuat. Guru biasa dapat dijadikan Admin oleh Super Admin.</p></div><div class="toolbar"><input id="teacherSearch" class="search" placeholder="Cari nama..."><button class="btn primary" onclick="openTeacherForm()">+ Tambah</button></div></div><div id="teachersTable"></div>`;$('#teacherSearch').oninput=renderTeachersTable;renderTeachersTable();}
function renderTeachersTable(){const root=$('#teachersTable');if(!root)return;const q=normalize($('#teacherSearch')?.value);const arr=state.teachers.filter(t=>!q||normalize(`${t.name} ${t.type} ${t.email}`).includes(q)).sort((a,b)=>a.name.localeCompare(b.name));root.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Nama</th><th>Jenis</th><th>Alias Jadwal</th><th>Akun</th><th>Hak Akses</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${arr.map(t=>{const u=state.users.find(x=>x.id===t.accountId);const aliases=Object.entries(state.teacherAliases).filter(([,id])=>id===t.id).map(([a])=>a).join(', ');return `<tr><td><strong>${esc(t.name)}</strong><br><span class="muted">${esc(t.email||'Belum aktivasi')}</span></td><td>${esc(t.type||'Belum ditentukan')}</td><td>${esc(aliases||'-')}</td><td>${u?'<span class="status active">Aktif</span>':'<span class="status pending">Belum aktif</span>'}</td><td>${u?esc(roleLabel(u)):'-'}</td><td><span class="status ${t.status==='Aktif'?'active':'inactive'}">${esc(t.status)}</span></td><td><button class="btn secondary small" onclick="openTeacherForm('${t.id}')">Edit</button>${currentUser.role==='superadmin'&&u?` <button class="btn warning small" onclick="toggleTeacherRole('${t.id}')">${u.role==='admin'?'Jadikan Biasa':'Jadikan Admin'}</button>`:''}${currentUser.role==='superadmin'&&!u?` <button class="btn ghost small" onclick="createTempAccount('${t.id}')">Sandi Sementara</button>`:''}</td></tr>`;}).join('')}</tbody></table></div>`;}
function openTeacherForm(id=''){const t=getTeacher(id)||{name:'',type:'Belum ditentukan',status:'Aktif',subject:''};openModal(id?'Edit Guru/Tendik':'Tambah Guru/Tendik','DATA PEGAWAI',`<form id="teacherForm" class="form-grid"><label>Nama<input id="tfName" value="${esc(t.name)}" required></label><label>Jenis<select id="tfType"><option ${t.type==='Guru'?'selected':''}>Guru</option><option ${t.type==='Tendik'?'selected':''}>Tendik</option><option ${t.type==='Belum ditentukan'?'selected':''}>Belum ditentukan</option></select></label><label>Mapel Utama<input id="tfSubject" value="${esc(t.subject||'')}" placeholder="Opsional"></label><label>Status<select id="tfStatus"><option ${t.status==='Aktif'?'selected':''}>Aktif</option><option ${t.status!=='Aktif'?'selected':''}>Nonaktif</option></select></label><div class="full notice info">Tendik tetap dapat menggantikan guru jika kelas ditandai <b>Butuh Pengganti</b>.</div><div class="full"><button class="btn primary">Simpan</button></div></form>`);$('#teacherForm').onsubmit=e=>{e.preventDefault();const name=$('#tfName').value.trim();if(id){t.name=name;t.type=$('#tfType').value;t.subject=$('#tfSubject').value.trim();t.status=$('#tfStatus').value;const u=state.users.find(x=>x.id===t.accountId);if(u)u.name=name;}else state.teachers.push({id:uid('tch'),name,type:$('#tfType').value,subject:$('#tfSubject').value.trim(),role:'guru',status:$('#tfStatus').value,email:'',accountId:null});refreshScheduleLinks();saveState();closeModal();renderTeachers();refreshRegisterTeachers();toast('Data tersimpan.');};}
function toggleTeacherRole(id){if(currentUser.role!=='superadmin')return;const t=getTeacher(id),u=state.users.find(x=>x.id===t?.accountId);if(!u)return;u.role=u.role==='admin'?'guru':'admin';t.role=u.role;saveState();logAction(`${t.name} diubah menjadi ${roleLabel(u)}.`);renderTeachers();}
function createTempAccount(id){if(currentUser.role!=='superadmin')return;const t=getTeacher(id);if(!t||t.accountId)return;const pw=prompt('Sandi sementara untuk '+t.name,'SH123456');if(!pw)return;const u={id:uid('usr'),teacherId:t.id,name:t.name,email:'',password:pw,role:'guru',status:'Aktif'};state.users.push(u);t.accountId=u.id;saveState();refreshRegisterTeachers();renderTeachers();alert(`Akun sementara dibuat.\nLogin: ${t.name}\nPassword: ${pw}\nMinta pengguna mengganti password setelah sistem online.`);}

function renderMaster(){setTitle('DATA MASTER','Kelas & Mata Pelajaran');const c=$('#pageContent');c.innerHTML=`<div class="grid cols-2"><div><div class="section-head" style="margin-top:0"><div><h3>Kelas</h3></div><button class="btn primary small" onclick="openClassForm()">+ Kelas</button></div><div class="card">${state.classes.map(x=>`<div class="schedule-card" style="margin-bottom:8px"><div class="schedule-info"><h4>${esc(x.name)}</h4><p>${esc(x.unit||'-')} • ${state.students.filter(s=>s.status==='Aktif'&&s.classId===x.id).length} siswa</p></div><button class="btn secondary small" onclick="openClassForm('${x.id}')">Edit</button></div>`).join('')}</div></div><div><div class="section-head" style="margin-top:0"><div><h3>Mata Pelajaran</h3></div><button class="btn primary small" onclick="openSubjectForm()">+ Mapel</button></div><div class="card">${state.subjects.map(x=>`<div class="schedule-card" style="margin-bottom:8px"><div class="schedule-info"><h4>${esc(x.name)}</h4></div><button class="btn secondary small" onclick="openSubjectForm('${x.id}')">Edit</button></div>`).join('')}</div></div></div>`;}
function openClassForm(id=''){const x=getClass(id)||{name:'',unit:'Putra',active:true};openModal(id?'Edit Kelas':'Tambah Kelas','KELAS',`<form id="classForm" class="stack"><label>Nama Kelas<input id="cfName" value="${esc(x.name)}" required></label><label>Unit<select id="cfUnit"><option ${x.unit==='Putra'?'selected':''}>Putra</option><option ${x.unit==='Putri'?'selected':''}>Putri</option></select></label><label>Status<select id="cfActive"><option value="1" ${x.active?'selected':''}>Aktif</option><option value="0" ${!x.active?'selected':''}>Nonaktif</option></select></label><button class="btn primary">Simpan</button></form>`);$('#classForm').onsubmit=e=>{e.preventDefault();if(id){x.name=$('#cfName').value.trim();x.unit=$('#cfUnit').value;x.active=$('#cfActive').value==='1';state.students.filter(s=>s.classId===x.id).forEach(s=>s.className=x.name);}else state.classes.push({id:uid('cls'),name:$('#cfName').value.trim(),unit:$('#cfUnit').value,active:true});saveState();closeModal();renderMaster();};}
function openSubjectForm(id=''){const x=state.subjects.find(c=>c.id===id)||{name:''};openModal(id?'Edit Mapel':'Tambah Mapel','MATA PELAJARAN',`<form id="subjectForm" class="stack"><label>Nama Mata Pelajaran<input id="subName" value="${esc(x.name)}" required></label><button class="btn primary">Simpan</button></form>`);$('#subjectForm').onsubmit=e=>{e.preventDefault();if(id)x.name=$('#subName').value.trim();else state.subjects.push({id:uid('sub'),name:$('#subName').value.trim()});saveState();closeModal();renderMaster();};}

function renderYears(){setTitle('PENGATURAN AKADEMIK','Tahun Ajaran');const c=$('#pageContent'),active=getActiveYear();c.innerHTML=`<div class="section-head" style="margin-top:0"><div><h3>Tahun Ajaran & Semester</h3><p>Data lama tidak dihapus saat tahun ajaran berganti.</p></div><div class="toolbar"><button class="btn secondary" onclick="openPromotion()">Proses Naik Kelas</button><button class="btn primary" onclick="openYearForm()">+ Tahun Ajaran</button></div></div><div class="grid cols-3">${state.academicYears.map(y=>`<div class="card"><p class="eyebrow">TAHUN AJARAN</p><h3 style="margin:0 0 8px">${esc(y.name)}</h3><p class="muted">Semester ${esc(y.semester)}</p>${active?.id===y.id?'<span class="status active">Aktif</span>':`<button class="btn secondary small" onclick="activateYear('${y.id}')">Aktifkan</button>`}</div>`).join('')}</div><div class="notice info" style="margin-top:16px">Saat tahun ajaran baru dibuat, siswa lama cukup diproses melalui <b>Naik Kelas</b>. Kelas XII dapat diubah menjadi <b>Lulus</b>.</div>`;}
function openYearForm(){openModal('Tambah Tahun Ajaran','TAHUN AJARAN',`<form id="yearForm" class="form-grid"><label>Tahun Ajaran<input id="yfName" placeholder="2027/2028" required></label><label>Semester<select id="yfSemester"><option>1</option><option>2</option></select></label><div class="full"><button class="btn primary">Simpan & Aktifkan</button></div></form>`);$('#yearForm').onsubmit=e=>{e.preventDefault();const y={id:uid('yr'),name:$('#yfName').value.trim(),semester:$('#yfSemester').value,isActive:true};state.academicYears.forEach(x=>x.isActive=false);state.academicYears.push(y);state.settings.activeAcademicYearId=y.id;saveState();closeModal();renderYears();toast('Tahun ajaran aktif diperbarui.');};}
function activateYear(id){state.academicYears.forEach(x=>x.isActive=x.id===id);state.settings.activeAcademicYearId=id;saveState();renderYears();}
function openPromotion(){const active=getActiveYear();if(!active)return;const currentClasses=[...new Set(state.students.filter(s=>s.status==='Aktif').map(s=>s.classId).filter(Boolean))].map(getClass).filter(Boolean);openModal('Proses Naik Kelas','TAHUN AJARAN',`<div class="notice info">Tahun aktif: <b>${esc(active.name)}</b>. Tentukan tujuan setiap kelas.</div><form id="promotionForm" class="stack" style="margin-top:14px">${currentClasses.map(c=>`<label>${esc(c.name)}<select data-promote="${c.id}"><option value="KEEP">Tetap</option>${state.classes.filter(x=>x.active&&x.id!==c.id).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}<option value="GRAD">Lulus</option></select></label>`).join('')}<button class="btn primary">Proses</button></form>`);$('#promotionForm').onsubmit=e=>{e.preventDefault();if(!confirm('Proses kenaikan kelas sekarang? Riwayat lama tetap disimpan.'))return;let n=0;$$('[data-promote]').forEach(sel=>{const from=sel.dataset.promote,to=sel.value;state.students.filter(s=>s.status==='Aktif'&&s.classId===from).forEach(s=>{s.history=s.history||[];s.history.push({academicYear:s.academicYear,classId:s.classId,className:s.className,status:s.status});if(to==='GRAD')s.status='Lulus';else{const cls=to==='KEEP'?getClass(from):getClass(to);s.classId=cls?.id||s.classId;s.className=cls?.name||s.className;s.academicYear=active.name;}n++;});});saveState();closeModal();renderYears();toast(`${n} siswa diproses.`);};}

function renderSchedule(){setTitle('AKADEMIK','Jadwal');const c=$('#pageContent'),isTeacher=currentUser.role==='guru',t=getMyTeacher();const relevant=isTeacher?state.schedules.filter(s=>s.teacherId===t?.id):state.schedules;const aliasWarn=unresolvedAliasCount(),classWarn=unresolvedClassCount();c.innerHTML=`${!isTeacher&&(aliasWarn||classWarn)?`<div class="notice warning"><b>Perlu pemetaan:</b> ${aliasWarn} kode guru dan ${classWarn} kelas belum terhubung. <button class="link-btn" onclick="openScheduleMapping()">Buka Pemetaan</button></div>`:''}<div class="section-head" style="margin-top:${aliasWarn||classWarn?'14px':'0'}"><div><h3>${isTeacher?'Jadwal Mengajar Saya':'Jadwal Pelajaran 2026/2027'}</h3><p>${state.meta.scheduleSlots||state.schedules.length} slot dari file jadwal. Jam berurutan digabung ketika guru mengabsen.</p></div>${!isTeacher?`<div class="toolbar"><button class="btn ghost" onclick="openScheduleMapping()">Pemetaan</button><button class="btn secondary" onclick="openScheduleImport()">Import Excel</button><button class="btn primary" onclick="openScheduleForm()">+ Jadwal</button></div>`:''}</div>${!relevant.length?'<div class="card empty">Belum ada jadwal untuk akun ini.</div>':`<div class="table-wrap"><table><thead><tr><th>Hari</th><th>Jam</th><th>Waktu</th><th>Kelas</th><th>Mapel</th><th>Guru</th><th>Status</th>${!isTeacher?'<th>Aksi</th>':''}</tr></thead><tbody>${relevant.slice().sort((a,b)=>SCHOOL_DAYS.indexOf(a.day)-SCHOOL_DAYS.indexOf(b.day)||byTime(a,b)).map(s=>`<tr><td>${esc(s.day)}</td><td>${esc(s.period)}</td><td>${esc(s.start)}–${esc(s.end)}</td><td>${esc(s.scheduleClassName)}${!s.classId?'<br><span class="danger-text">Belum dipetakan</span>':''}</td><td>${esc(s.subjectName)}</td><td>${esc(s.teacherName)}</td><td>${s.needsSubstitute?'<span class="status pending">Butuh Pengganti</span>':'<span class="status active">Normal</span>'}</td>${!isTeacher?`<td><button class="btn secondary small" onclick="openScheduleForm('${s.id}')">Edit</button> <button class="btn warning small" onclick="toggleSubstitute('${s.id}')">${s.needsSubstitute?'Batalkan':'Butuh Pengganti'}</button></td>`:''}</tr>`).join('')}</tbody></table></div>`}`;}
function openScheduleMapping(){if(currentUser.role==='guru')return;const aliases=Object.keys(state.teacherAliases).sort(),classes=Object.keys(state.scheduleClassMap);openModal('Pemetaan Jadwal','SETUP JADWAL',`<div class="notice info">Kode yang sudah jelas sudah dipetakan otomatis. Pilih hanya yang belum jelas. Perubahan berlaku ke seluruh jadwal.</div><h4 style="margin-top:18px">Kode Guru</h4><div class="mapping-list">${aliases.map(a=>`<label class="mapping-row"><span><b>${esc(a)}</b><small>${state.schedules.filter(s=>s.teacherAlias===a).length} slot</small></span><select data-alias="${esc(a)}"><option value="">— Belum dipetakan —</option>${state.teachers.filter(t=>t.status==='Aktif').sort((a,b)=>a.name.localeCompare(b.name)).map(t=>`<option value="${t.id}" ${state.teacherAliases[a]===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>`).join('')}</div><h4 style="margin-top:20px">Kelas pada File Jadwal</h4><div class="mapping-list">${classes.map(n=>`<label class="mapping-row"><span><b>${esc(n)}</b></span><select data-classmap="${esc(n)}"><option value="">— Belum dipetakan —</option>${state.classes.filter(c=>c.active).map(c=>`<option value="${c.id}" ${state.scheduleClassMap[n]===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`).join('')}</div><button class="btn primary full" id="saveMappingBtn" style="margin-top:18px">Simpan Pemetaan</button>`);$('#saveMappingBtn').onclick=()=>{$$('[data-alias]').forEach(sel=>state.teacherAliases[sel.dataset.alias]=sel.value||null);$$('[data-classmap]').forEach(sel=>state.scheduleClassMap[sel.dataset.classmap]=sel.value||null);refreshScheduleLinks();saveState();logAction('Pemetaan jadwal diperbarui.');closeModal();renderSchedule();toast('Pemetaan tersimpan.');};}
function parseScheduleCell(raw){const tokens=String(raw||'').split('/').map(x=>x.trim()).filter(Boolean);if(tokens.length<2)return {subjectName:String(raw||'').trim(),teacherAlias:''};const first=tokens[0].toUpperCase(),last=tokens[tokens.length-1].toUpperCase();const firstKnown=Object.prototype.hasOwnProperty.call(state.teacherAliases,first);const lastKnown=Object.prototype.hasOwnProperty.call(state.teacherAliases,last);let alias,subjectParts;if(firstKnown&&!lastKnown){alias=first;subjectParts=tokens.slice(1);}else{alias=last;subjectParts=tokens.slice(0,-1);}const map={'MTK':'Matematika','PAI':'PAI','EKO':'Ekonomi','B. INGGRIS':'Bahasa Inggris','B.INDO':'Bahasa Indonesia','B. INDO':'Bahasa Indonesia','KIMIA':'Kimia','BIOLOGI':'Biologi','SOSIO':'Sosiologi','INFOR':'Informatika','CODING':'Coding','INFOR/CODING':'Informatika/Coding','SEJARAH':'Sejarah','GEO':'Geografi','FISIKA':'Fisika','PJOK':'PJOK','PKN':'PKN'};const subjectName=subjectParts.map(x=>map[x.toUpperCase()]||titleCase(x)).join(' / ');return {subjectName,teacherAlias:alias};}
function openScheduleImport(){openModal('Import Jadwal Excel','IMPORT JADWAL',`<div class="notice info">Format seperti file <b>Jadwal 2026</b>: kelas di baris header, hari di kolom A, jam di B, waktu di C, lalu isi jadwal per kelas.</div><div class="stack" style="margin-top:14px"><label>Pilih file Excel<input id="scheduleImportFile" type="file" accept=".xlsx,.xls"></label><div id="scheduleImportPreview"></div><button class="btn primary" id="runScheduleImport">Baca & Ganti Jadwal</button></div>`);$('#runScheduleImport').onclick=importScheduleFile;}
async function importScheduleFile(){const file=$('#scheduleImportFile').files[0];if(!file)return toast('Pilih file terlebih dahulu.');if(typeof XLSX==='undefined')return alert('Pustaka Excel belum termuat.');const data=await file.arrayBuffer(),wb=XLSX.read(data,{type:'array'}),ws=wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(ws,{header:1,defval:''});let headerRow=rows.findIndex(r=>String(r[2]).trim().toUpperCase()==='WAKTU');if(headerRow<0)return alert('Baris WAKTU tidak ditemukan.');const headers=rows[headerRow].slice(3).map(x=>String(x).trim());let day='',newSchedules=[];for(let i=headerRow+1;i<rows.length;i++){const row=rows[i];if(String(row[0]).trim())day=titleCase(String(row[0]).trim());const period=String(row[1]||'').trim(),time=String(row[2]||'').trim();if(!period||!time)continue;const parts=time.split('-').map(x=>x.trim());for(let j=3;j<row.length;j++){const raw=String(row[j]||'').trim();if(!raw)continue;const className=headers[j-3];if(!className)continue;const parsed=parseScheduleCell(raw);if(!Object.prototype.hasOwnProperty.call(state.teacherAliases,parsed.teacherAlias))state.teacherAliases[parsed.teacherAlias]=null;if(!Object.prototype.hasOwnProperty.call(state.scheduleClassMap,className))state.scheduleClassMap[className]=null;let sub=state.subjects.find(s=>normalize(s.name)===normalize(parsed.subjectName));if(!sub){sub={id:uid('sub'),name:parsed.subjectName};state.subjects.push(sub);}newSchedules.push({id:uid('sch'),day,period,start:parts[0]||'',end:parts[1]||'',scheduleClassName:className,classId:state.scheduleClassMap[className]||null,className,subjectId:sub.id,subjectName:parsed.subjectName,subjectRaw:raw,teacherAlias:parsed.teacherAlias,teacherId:state.teacherAliases[parsed.teacherAlias]||null,teacherName:parsed.teacherAlias,needsSubstitute:false,reason:'',source:file.name});}}
  if(!newSchedules.length)return alert('Tidak ada jadwal yang terbaca.');if(!confirm(`Ditemukan ${newSchedules.length} slot jadwal. Ganti jadwal saat ini?`))return;state.schedules=newSchedules;refreshScheduleLinks();saveState();logAction(`Jadwal diimpor dari ${file.name}: ${newSchedules.length} slot.`);$('#scheduleImportPreview').innerHTML=`<div class="notice success">${newSchedules.length} slot berhasil diimpor.</div>`;setTimeout(()=>{closeModal();renderSchedule();},500);
}
function openScheduleForm(id=''){const s=state.schedules.find(x=>x.id===id)||{day:'Sabtu',period:'1',start:'13:30',end:'14:00',classId:'',scheduleClassName:'',subjectId:'',teacherId:''};openModal(id?'Edit Jadwal':'Tambah Jadwal','JADWAL',`<form id="scheduleForm" class="form-grid"><label>Hari<select id="scDay">${SCHOOL_DAYS.map(x=>`<option ${s.day===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Jam Ke<input id="scPeriod" value="${esc(s.period||'1')}" required></label><label>Mulai<input id="scStart" type="time" value="${esc(s.start||'13:30')}" required></label><label>Selesai<input id="scEnd" type="time" value="${esc(s.end||'14:00')}" required></label><label>Kelas Siswa<select id="scClass" required><option value="">Pilih kelas...</option>${state.classes.filter(x=>x.active).map(x=>`<option value="${x.id}" ${s.classId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Mapel<select id="scSubject" required><option value="">Pilih mapel...</option>${state.subjects.map(x=>`<option value="${x.id}" ${s.subjectId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="full">Guru/Tendik<select id="scTeacher" required><option value="">Pilih...</option>${state.teachers.filter(x=>x.status==='Aktif').map(x=>`<option value="${x.id}" ${s.teacherId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><div class="full"><button class="btn primary">Simpan Jadwal</button></div></form>`);$('#scheduleForm').onsubmit=e=>{e.preventDefault();const cls=getClass($('#scClass').value),sub=state.subjects.find(x=>x.id===$('#scSubject').value),t=getTeacher($('#scTeacher').value);const alias=Object.entries(state.teacherAliases).find(([,tid])=>tid===t.id)?.[0]||t.name.split(' ')[0].toUpperCase();state.teacherAliases[alias]=t.id;const scName=s.scheduleClassName||cls.name;state.scheduleClassMap[scName]=cls.id;const p={day:$('#scDay').value,period:$('#scPeriod').value,start:$('#scStart').value,end:$('#scEnd').value,scheduleClassName:scName,classId:cls.id,className:scName,subjectId:sub.id,subjectName:sub.name,teacherAlias:alias,teacherId:t.id,teacherName:t.name};const conflict=state.schedules.find(x=>x.id!==id&&x.day===p.day&&x.teacherId===p.teacherId&&x.start===p.start);if(conflict&&!confirm(`Konflik: ${t.name} juga terjadwal pada ${p.start}. Tetap simpan?`))return;if(id)Object.assign(s,p);else state.schedules.push({id:uid('sch'),...p,needsSubstitute:false,reason:'',source:'Manual'});saveState();closeModal();renderSchedule();toast('Jadwal tersimpan.');};}
function toggleSubstitute(id){const s=state.schedules.find(x=>x.id===id);if(!s)return;const block=blockFromSchedule(id)||{scheduleIds:[id]};const newVal=!s.needsSubstitute;let reason='';if(newVal)reason=prompt('Alasan guru berhalangan (opsional):','Izin')||'';block.scheduleIds.forEach(sid=>{const x=state.schedules.find(k=>k.id===sid);if(x){x.needsSubstitute=newVal;x.reason=reason;}});saveState();renderSchedule();}

function renderAttendanceHub(){setTitle('ABSENSI','Isi Absensi');const c=$('#pageContent'),t=getMyTeacher(),day=dayName(),done=scheduleDoneIds();const own=scheduleBlocks(day,s=>s.teacherId===t?.id).filter(b=>!b.scheduleIds.every(id=>done.has(id)));const replacements=scheduleBlocks(day,s=>s.needsSubstitute&&s.teacherId!==t?.id).filter(b=>!b.scheduleIds.every(id=>done.has(id)));c.innerHTML=`<div class="section-head" style="margin-top:0"><div><h3>Pilih Jadwal</h3><p>Hadir Semua → ubah pengecualian → foto → simpan.</p></div></div>${own.length?`<div class="grid">${own.map(b=>scheduleCardTeacher(b,false)).join('')}</div>`:'<div class="card empty">Tidak ada jadwal Anda yang menunggu absensi.</div>'}<div class="section-head"><div><h3>Pengganti</h3><p>Kelas yang ditandai Admin membutuhkan pengganti.</p></div></div>${replacements.length?`<div class="grid">${replacements.map(b=>scheduleCardTeacher(b,false,true)).join('')}</div>`:'<div class="card empty">Tidak ada kelas yang membutuhkan pengganti.</div>'}`;}
function startAttendance(scheduleId,isSubstitute=false){const block=blockFromSchedule(scheduleId);if(!block)return;const teacher=getMyTeacher();if(!teacher)return toast('Akun belum terhubung ke data pegawai.');if(!block.classId)return alert(`Kelas ${block.scheduleClassName} belum dipetakan ke Data Siswa. Hubungi Admin untuk melakukan pemetaan jadwal.`);if(isSubstitute&&!confirm(`Anda akan menggantikan ${block.teacherName} di ${block.scheduleClassName}. Lanjut?`))return;const students=state.students.filter(st=>st.status==='Aktif'&&st.classId===block.classId).sort((a,b)=>a.name.localeCompare(b.name));if(!students.length)return alert(`Tidak ada siswa aktif yang terhubung ke ${block.scheduleClassName}.`);const rows=students.map(st=>`<div class="attendance-row" data-student="${st.id}"><div class="attendance-name"><strong>${esc(st.name)}</strong><span>${esc(st.nis||'Tanpa NIS')}</span></div><select class="attStatus">${ATT_STATUSES.map(x=>`<option ${x==='Hadir'?'selected':''}>${x}</option>`).join('')}</select><input class="attendance-note" placeholder="Keterangan"></div>`).join('');openModal(`${block.scheduleClassName} • ${block.subjectName}`,'ABSENSI',`<div class="notice info"><b>${esc(block.start)}–${esc(block.end)}</b> • Jam ${esc(block.periods.join(','))}<br>Guru terjadwal: ${esc(block.teacherName)}${isSubstitute?` • <b>Anda sebagai pengganti</b>`:''}</div><div class="attendance-toolbar"><button class="btn success" id="allPresentBtn">✓ Hadir Semua</button><div id="attSummary" class="summary-pills"></div></div><div id="attRows">${rows}</div><div class="divider"></div><label>Foto Bukti Kehadiran<input id="attendancePhoto" type="file" accept="image/*" capture="environment"></label><img id="photoPreview" class="photo-preview hidden" alt="Preview"><div class="toolbar" style="margin-top:16px"><button class="btn primary full" id="saveAttendanceBtn">Simpan Absensi</button></div>`);const update=()=>{const vals=$$('.attStatus').map(x=>x.value);$('#attSummary').innerHTML=ATT_STATUSES.map(st=>`<span class="pill">${st}: ${vals.filter(v=>v===st).length}</span>`).join('');};$('#allPresentBtn').onclick=()=>{$$('.attStatus').forEach(x=>x.value='Hadir');update();};$$('.attStatus').forEach(x=>x.onchange=update);update();let photoData='';$('#attendancePhoto').onchange=async e=>{const f=e.target.files[0];if(!f)return;photoData=await compressImage(f);const img=$('#photoPreview');img.src=photoData;img.classList.remove('hidden');};$('#saveAttendanceBtn').onclick=()=>{if(state.settings.photoRequired&&!photoData)return toast('Foto wajib sebelum menyimpan.');const done=scheduleDoneIds();if(block.scheduleIds.every(id=>done.has(id)))return toast('Absensi sesi ini sudah tersimpan.');const session={id:uid('ats'),scheduleId:block.id,scheduleIds:block.scheduleIds,date:todayISO(),teacherId:teacher.id,teacherName:teacher.name,scheduledTeacherId:block.teacherId,scheduledTeacherName:block.teacherName,isSubstitute:!!isSubstitute,photo:photoData,createdAt:new Date().toISOString(),classId:block.classId,className:block.scheduleClassName,subjectName:block.subjectName,start:block.start,end:block.end};state.attendanceSessions.push(session);$$('[data-student]').forEach(row=>state.studentAttendance.push({id:uid('sta'),sessionId:session.id,studentId:row.dataset.student,status:$('.attStatus',row).value,note:$('.attendance-note',row).value.trim()}));ensureTeacherPresence(teacher);saveState();logAction(`${teacher.name} menyimpan absensi ${block.scheduleClassName} - ${block.subjectName}${isSubstitute?' sebagai pengganti':''}.`);closeModal();go('dashboard');toast('Absensi berhasil disimpan.');};}
async function compressImage(file){return new Promise(resolve=>{const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const max=900,scale=Math.min(1,max/img.width),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.68));};img.src=r.result;};r.readAsDataURL(file);});}

function renderReports(){setTitle('LAPORAN','Rekap');const c=$('#pageContent'),isTeacher=currentUser.role==='guru',t=getMyTeacher();const sessions=(isTeacher?state.attendanceSessions.filter(x=>x.teacherId===t?.id):state.attendanceSessions).slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt));const counts=ATT_STATUSES.reduce((o,k)=>(o[k]=0,o),{});const sessionIds=new Set(sessions.map(x=>x.id));state.studentAttendance.filter(a=>sessionIds.has(a.sessionId)).forEach(a=>counts[a.status]=(counts[a.status]||0)+1);let teacherRows='';if(!isTeacher){teacherRows=state.teachers.filter(t=>t.status==='Aktif').map(t=>{const taught=state.attendanceSessions.filter(s=>s.teacherId===t.id).length,sub=state.attendanceSessions.filter(s=>s.teacherId===t.id&&s.isSubstitute).length,pres=state.teacherPresence.filter(p=>p.teacherId===t.id).length;return `<tr><td><strong>${esc(t.name)}</strong><br><span class="muted">${esc(t.type||'')}</span></td><td>${pres}</td><td>${taught}</td><td>${sub}</td></tr>`;}).join('');}
  c.innerHTML=`<div class="grid cols-4">${ATT_STATUSES.slice(0,4).map((x,i)=>stat(['✓','✚','i','×'][i],counts[x]||0,x)).join('')}</div>${!isTeacher?`<div class="section-head"><div><h3>Rekap Aktivitas Guru/Tendik</h3><p>Jumlah hari hadir dan sesi mengajar pada data lokal saat ini.</p></div></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Hari Hadir</th><th>Sesi Mengajar</th><th>Sebagai Pengganti</th></tr></thead><tbody>${teacherRows}</tbody></table></div>`:''}<div class="section-head"><div><h3>Riwayat Sesi Absensi</h3><p>${isTeacher?'Sesi yang Anda isi.':'Seluruh sesi tersimpan.'}</p></div></div>${sessions.length?`<div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Waktu</th><th>Kelas</th><th>Mapel</th><th>Pengajar</th><th>Guru Terjadwal</th><th>Status</th><th>Foto</th></tr></thead><tbody>${sessions.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.start||'-')}–${esc(x.end||'-')}</td><td>${esc(x.className||'-')}</td><td>${esc(x.subjectName||'-')}</td><td>${esc(x.teacherName)}</td><td>${esc(x.scheduledTeacherName)}</td><td>${x.isSubstitute?'<span class="status pending">Pengganti</span>':'<span class="status active">Normal</span>'}</td><td>${x.photo?`<button class="btn secondary small" onclick="viewPhoto('${x.id}')">Lihat</button>`:'-'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty">Belum ada rekap absensi.</div>'}`;}
function viewPhoto(id){const x=state.attendanceSessions.find(s=>s.id===id);if(x?.photo)openModal('Foto Bukti','ABSENSI',`<img src="${x.photo}" class="photo-preview" style="max-height:none">`);}

function renderGuide(){setTitle('BANTUAN','Panduan');const c=$('#pageContent');c.innerHTML=`<div class="grid cols-2"><div class="card"><p class="eyebrow">UNTUK GURU/TENDIK</p><h3>Absensi kelas</h3><ol><li>Catat kehadiran diri dengan <b>Saya Hadir</b>.</li><li>Buka jadwal, tekan <b>Isi Absensi</b>.</li><li>Tekan <b>Hadir Semua</b>, lalu ubah siswa yang Sakit, Izin, Alpa, atau Terlambat.</li><li>Ambil foto dan simpan.</li></ol></div><div class="card"><p class="eyebrow">AKUN</p><h3>Aktivasi sendiri</h3><p>Pilih nama yang sudah terdaftar, isi email dan password. Jika nama tidak ada, hubungi Admin.</p></div><div class="card"><p class="eyebrow">PENGGANTI</p><h3>Guru atau Tendik</h3><p>Admin menandai kelas <b>Butuh Pengganti</b>. Guru maupun Tendik dapat mengambil kelas tersebut tanpa mengubah guru asli pada jadwal.</p></div><div class="card"><p class="eyebrow">TAHUN AJARAN</p><h3>Naik kelas tanpa hapus riwayat</h3><p>Buat tahun ajaran baru, aktifkan, lalu proses naik kelas. Siswa berhenti dan lulus tetap disimpan sebagai riwayat.</p></div></div>`;}
function renderSettings(){setTitle('SISTEM','Pengaturan');const c=$('#pageContent');c.innerHTML=`<div class="grid cols-2"><div class="card"><h3>Pengaturan Absensi</h3><label style="margin-top:14px">Foto Bukti<select id="photoRequired"><option value="0" ${!state.settings.photoRequired?'selected':''}>Tidak wajib</option><option value="1" ${state.settings.photoRequired?'selected':''}>Wajib</option></select></label><button class="btn primary" style="margin-top:12px" onclick="saveSettings()">Simpan</button></div><div class="card"><h3>Status Data Awal</h3><p class="muted">${state.meta.activeStudentCount||0} siswa aktif • ${state.meta.stoppedStudentCount||0} berhenti • ${state.meta.scheduleSlots||state.schedules.length} slot jadwal.</p><p class="muted">Ini masih versi lokal; jangan dipublikasikan sebagai sistem produksi karena database dan autentikasi belum berada di server aman.</p><button class="btn danger" onclick="resetDemo()">Reset ke Data Awal</button></div></div><div class="section-head"><div><h3>Log Aktivitas</h3></div></div><div class="card">${state.activityLogs.length?state.activityLogs.slice(0,40).map(x=>`<div class="log-row"><strong>${esc(x.text)}</strong><span>${new Date(x.at).toLocaleString('id-ID')}</span></div>`).join(''):'Belum ada aktivitas.'}</div>`;}
function saveSettings(){state.settings.photoRequired=$('#photoRequired').value==='1';saveState();toast('Pengaturan disimpan.');}
function openProfile(){const t=getMyTeacher();openModal(currentUser.name,'PROFIL',`<div class="stack"><div class="card" style="box-shadow:none"><p class="eyebrow">AKSES</p><h3 style="margin:0">${esc(roleLabel())}</h3><p class="muted">${esc(currentUser.email||'Login dengan nama')}</p>${t?`<p class="muted">Jenis: ${esc(t.type||'Belum ditentukan')}</p>`:''}</div><button class="btn secondary" onclick="logout();closeModal()">Keluar dari Aplikasi</button></div>`);}
function openModal(title,eyebrow,body){$('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=body;$('#modal').classList.remove('hidden');$('#modal').setAttribute('aria-hidden','false');$$('[data-close-modal]').forEach(x=>x.onclick=closeModal);}
function closeModal(){$('#modal').classList.add('hidden');$('#modal').setAttribute('aria-hidden','true');}

initAuth(); showApp();
